class Solution {
public:
    int maxDistance(std::vector<std::vector<int>>& arrays) {
        int mn = arrays[0].front(), mx = arrays[0].back(), ans = 0;
        for (int i = 1; i < (int)arrays.size(); ++i) {
            ans = std::max(ans, arrays[i].back() - mn);
            ans = std::max(ans, mx - arrays[i].front());
            mn = std::min(mn, arrays[i].front());
            mx = std::max(mx, arrays[i].back());
        }
        return ans;
    }
};
